def parse_arg_line(rest, cont):
    raw_tokens = rest.split()
    if not raw_tokens:
        return None
    def_token = raw_tokens[0]
    idx = 1
    notations = []
    env_token = None
    while idx < len(raw_tokens):
        t = raw_tokens[idx]
        if t.startswith("<") and t.endswith(">"):
            notations.append(t[1:-1])
            idx += 1
        elif t == "$$" or t.startswith("$"):
            env_token = t
            idx += 1
            break
        else:
            break
    if idx < len(raw_tokens) and (raw_tokens[idx] == "$$" or raw_tokens[idx].startswith("$")):
        env_token = raw_tokens[idx]
        idx += 1
    describe = " ".join(raw_tokens[idx:]) if idx < len(raw_tokens) else ""
    if cont:
        if describe:
            describe = describe + "\n\n" + cont
        else:
            describe = cont
    info = parse_arg_token(def_token)
    if notations:
        notation = notations[0]
    else:
        notation = info["id"].upper()
    env = None
    if env_token:
        if env_token == "$$":
            env = info["id"].upper()
        else:
            env = env_token[1:]
    return {
        "id": info["id"],
        "describe": describe,
        "notation": notation,
        "required": info["required"],
        "multiple": info["multiple"],
        "delimiter": info["delimiter"],
        "terminated": info["terminated"],
        "default": info["default"],
        "choice": info["choice"],
        "env": env,
    }

def parse_env_line(rest, cont):
    rest = rest.strip()
    if not rest:
        return None
    parts = rest.split(None, 1)
    def_token = parts[0]
    describe = parts[1] if len(parts) > 1 else ""
    if cont:
        if describe:
            describe = describe + "\n\n" + cont
        else:
            describe = cont
    info = parse_arg_token(def_token)
    return {
        "id": info["id"],
        "describe": describe,
        "required": info["required"],
        "default": info["default"],
        "choice": info["choice"],
        "inherited": False,
    }

